#include <bits/stdc++.h>
using namespace std;

void solve(istream &in, ostream &out) {
    int n, x;
    in >> n >> x;
    int ans = -1;
    int moves = n % 6;
    int balls[3] = {0, 0, 0};
    balls[x] = 1;
    for (int i = moves; i >= 1; --i) {
        if (i % 2 == 0) {
            int temp = balls[2];
            balls[2] = balls[1];
            balls[1] = temp;
        } else {
            int temp = balls[1];
            balls[1] = balls[0];
            balls[0] = temp;
        }
    }
    for (int i = 0; i < 3; ++i) {
        if (balls[i] == 1) {
            ans = i;
            break;
        }
    }
    out << ans << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}

