import java.io.BufferedReader
import java.io.InputStream
import java.io.InputStreamReader
import java.io.PrintWriter
import java.util.*

/**
 * Created by enitihas on 20/6/17.
 */
fun main(args: Array<String>) {
    val sc = Scanner(BufferedReader(InputStreamReader(System.`in`)))
    val pw = PrintWriter(System.out)
    solve(sc,pw)
    sc.close()
    pw.close()
}

fun solve(sc: Scanner, pw: PrintWriter) {
    val n = sc.nextInt()
    val x = sc.nextInt()
    var ans = -1
    val moves = n%6
    val balls = intArrayOf(0,0,0)
    balls[x] = 1
    for (i in moves downTo 1) {
        if(i%2==0) {
            val temp = balls[2]
            balls[2] = balls[1]
            balls[1] = temp
        }
        else {
            val temp = balls[1]
            balls[1] = balls[0]
            balls[0] = temp
        }
    }
    ans = balls.indexOf(1)
    println(ans)
}
